//! Font atlas generated by tools/mkfont.py (Roboto Regular/Medium, Apache License 2.0).

pub struct Glyph {
    pub cp: u32,
    pub w: i32,
    pub h: i32,
    pub x0: i32,
    pub y0: i32,
    pub adv: i32,
    pub off: usize,
}

pub struct Font {
    pub size: i32,
    #[allow(dead_code)] // part of the atlas format, kept for line spacing
    pub ascent: i32,
    #[allow(dead_code)]
    pub descent: i32,
    pub glyphs: Vec<Glyph>,
    pub alpha: &'static [u8],
}

/// s/m/l/xl = Roboto Regular 12/14/20/26 px, sb/mb/lb = Roboto Medium 12/14/18 px.
pub struct Fonts {
    pub s: Font,
    pub sb: Font,
    pub m: Font,
    pub mb: Font,
    pub l: Font,
    pub lb: Font,
    #[allow(dead_code)] // reserved for large read-outs
    pub xl: Font,
}

static BLOB: &[u8] = include_bytes!("../assets/font.bin");

fn u16le(b: &[u8], o: usize) -> u16 {
    u16::from_le_bytes([b[o], b[o + 1]])
}
fn i16le(b: &[u8], o: usize) -> i16 {
    i16::from_le_bytes([b[o], b[o + 1]])
}
fn u32le(b: &[u8], o: usize) -> u32 {
    u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]])
}

impl Font {
    pub fn glyph(&self, ch: char) -> &Glyph {
        let cp = ch as u32;
        if (32..127).contains(&cp) {
            return &self.glyphs[(cp - 32) as usize];
        }
        self.glyphs.iter().skip(95).find(|g| g.cp == cp).unwrap_or(&self.glyphs[('?' as usize) - 32])
    }
    pub fn width(&self, s: &str) -> i32 {
        s.chars().map(|c| self.glyph(c).adv).sum()
    }
}

impl Fonts {
    pub fn load() -> Fonts {
        assert_eq!(&BLOB[0..4], b"OOSF");
        let count = u16le(BLOB, 4) as usize;
        assert_eq!(count, 7);
        let mut o = 6;
        let mut v = Vec::new();
        for _ in 0..count {
            let size = u16le(BLOB, o) as i32;
            let ascent = u16le(BLOB, o + 2) as i32;
            let descent = u16le(BLOB, o + 4) as i32;
            let n = u16le(BLOB, o + 6) as usize;
            let alen = u32le(BLOB, o + 8) as usize;
            o += 12;
            let mut glyphs = Vec::with_capacity(n);
            for _ in 0..n {
                glyphs.push(Glyph {
                    cp: u32le(BLOB, o),
                    w: i16le(BLOB, o + 4) as i32,
                    h: i16le(BLOB, o + 6) as i32,
                    x0: i16le(BLOB, o + 8) as i32,
                    y0: i16le(BLOB, o + 10) as i32,
                    adv: i16le(BLOB, o + 12) as i32,
                    off: u32le(BLOB, o + 16) as usize,
                });
                o += 20;
            }
            let alpha = &BLOB[o..o + alen];
            o += alen;
            v.push(Font { size, ascent, descent, glyphs, alpha });
        }
        let mut it = v.into_iter();
        let mut next = || it.next().unwrap();
        Fonts { s: next(), sb: next(), m: next(), mb: next(), l: next(), lb: next(), xl: next() }
    }
}
